body:
{
  "pains": [
    {
      "id": "pain:credits-burn-before-value",
      "statement": "I spent about $500 in credits testing a list and came out the other side with barely half of it usable.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Credits drain faster than expected and the bill is never the same twice.",
        "operational": "Every failed test, mis-keyed run and exploratory column bills the same as a production run, so learning and experimenting are metered at full price and nobody can forecast next month's spend before approving the plan.",
        "personal": "The person who championed the tool has to explain a variable line item to a finance team that budgeted a fixed one, and starts running fewer experiments to keep the number quiet."
      },
      "workflow": "Building a table in Clay: you add an enrichment column, run it across a few thousand rows to see if it works, and the run bills whether the provider returns anything useful or not. Bites again at month end, reconciling the Clay invoice against pipeline in HubSpot or Salesforce.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "First real table run at volume after the trial credits are gone",
          "cites": ["src:4", "src:12"]
        },
        {
          "event": "Finance asks for a forecast of next quarter's enrichment spend",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["economic_buyer", "champion", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I spent ~$500 and 13,000+ credits on 1,000 CXO-level leads and got 632 with a verified email.",
              "cites": ["src:4"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "Clay charges separately for personal and work emails, doubling your costs if you need both.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Half the enrichment budget goes to rows that never become a send, and the other half is spent proving that to themselves.",
          "fears": "That the number they quoted in the business case turns out to be a third of the real one.",
          "dream_outcome": "Knowing the cost of a run before pressing run, and paying only for rows that come back with something."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "Here's the biggest issue with Clay: it can get expensive.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "A usage line that swings month to month against a budget that does not.",
          "fears": "Signing an annual commit sized on a month when the team happened to be careful.",
          "dream_outcome": "A predictable per-account cost they can multiply by target account count and defend."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Most people burn Clay credits like they're printing money. Then complain Clay is expensive. The problem? They skip waterfall enrichment completely.",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "Self-censoring experiments because each one has a price tag.",
          "fears": "Being the person who burned the team's credits on a test that went nowhere.",
          "dream_outcome": "A sandbox where trying something costs nothing until it works."
        }
      },
      "segments": ["seg:agency", "seg:lean", "seg:revops"],
      "feature_ref": "feat:waterfall",
      "cites": ["src:4", "src:5", "src:12"]
    },
    {
      "id": "pain:no-code-that-isnt",
      "statement": "It's sold as a spreadsheet, but the day I had to write a formula and an HTTP column I realised I'd been handed a programming language.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "The blank table is intimidating and the first useful build takes far longer than the demo suggested.",
        "operational": "Conditional run logic, lookups, formulas and custom API columns reward people who think like engineers, so the tool concentrates in one or two hands instead of spreading across the team who were supposed to use it.",
        "personal": "Anyone who does not touch it weekly loses the thread and quietly stops opening it, which feels like a personal failure rather than a product one."
      },
      "workflow": "Day two after purchase, opening a blank Clay table to rebuild the list that used to live in a Google Sheet, and hitting run conditions, formula syntax and provider ordering before a single email has been written.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A second or third teammate is given a seat and does not use it",
          "cites": ["src:5"]
        },
        {
          "event": "The build turns out to need real code, not columns",
          "cites": ["src:13"]
        }
      ],
      "who_feels": ["end_user", "technical_evaluator", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "It feels overwhelming for users who don't use it daily.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Weeks of ramp before the tool returns anything, during which the old manual process still has to run in parallel.",
          "fears": "Being visibly slower in the new tool than they were in a spreadsheet.",
          "dream_outcome": "Getting a working list out on the first afternoon without asking anyone for help."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "I spend 90% of my time in custom python, JS, or SQL.",
              "cites": ["src:13"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Clay created a problem so they could sell the solution. Complexity arbitrage.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Time spent working around the platform's abstractions instead of inside them.",
          "fears": "Committing the team to a tool that still needs a coder, and paying for both.",
          "dream_outcome": "A platform where the hard 10% is scriptable and the easy 90% genuinely isn't."
        },
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "It's a platform so complex that it requires a translator.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Owning adoption for a tool nobody else on the team can drive.",
          "fears": "That the rollout is judged on seat usage, and usage never leaves their own login.",
          "dream_outcome": "Three teammates building their own tables without a training session."
        }
      },
      "segments": ["seg:lean", "seg:revops", "seg:agency"],
      "feature_ref": null,
      "feature_note": "Nothing in the listed product kills this. feat:claygents removes some manual research steps but does not remove formulas, run conditions or HTTP columns. What would kill it is templated, opinionated builds that produce a working table from an ICP description without the user touching logic.",
      "cites": ["src:2", "src:5", "src:13"]
    },
    {
      "id": "pain:janitorial-work-before-the-table",
      "statement": "The six hours of list cleanup before I ever open the tool is the part nobody puts in the case study.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Most of a build day is spent merging and deduping exports, not building.",
        "operational": "Lists arrive from Sales Navigator, niche databases, supplier exports and a CRM dump in four different shapes, and every one has to be standardised and deduped before enrichment can run at all, so the platform's time savings start after the slowest part is already done.",
        "personal": "The work is invisible: it never shows up in a case study or a QBR, so the person doing it looks slow rather than thorough."
      },
      "workflow": "Before Clay opens: pulling a Sales Nav export, a supplier CSV and a CRM dump, then merging, standardising formats and deduping in a spreadsheet so the import doesn't create garbage rows.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A new campaign needs a list from three sources that do not share a key",
          "cites": ["src:3"]
        },
        {
          "event": "Enrichment returns nonsense and the cause turns out to be the input, not the provider",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["end_user", "champion"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "The 6 hours of janitorial work before Clay is the part nobody puts in the case study.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Most GTM motions don't break in Clay. They break in the 6 hours before you open a table... because your inputs are a mess.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Close to a full day per campaign on work that produces no output anyone sees.",
          "fears": "Shipping a campaign built on a list they did not have time to clean properly.",
          "dream_outcome": "One place the target list already lives, clean and deduped, that campaigns are drawn from rather than assembled for."
        },
        "champion": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "This is the part most GTM teams underestimate: input quality is the bottleneck, not the tool.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Explaining why a tool bought to save time still takes a day per campaign.",
          "fears": "That leadership concludes the tool was the wrong buy when the bottleneck sits upstream of it.",
          "dream_outcome": "Campaign setup measured in minutes because the account list is already maintained."
        }
      },
      "segments": ["seg:agency", "seg:lean", "seg:revops"],
      "feature_ref": "feat:audiences",
      "cites": ["src:3"]
    },
    {
      "id": "pain:coverage-and-bounces",
      "statement": "I stacked every provider I could and still got 63% coverage and an 8% bounce rate on the ones I did get.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "A meaningful share of every enriched list has no usable contact, and some of what comes back is wrong.",
        "operational": "Waterfalling across providers lifts coverage without closing the gap, so campaign volume is set by match rate rather than by target list size, and the unmatched remainder either gets dropped or gets guessed at, which is how bounces enter the sending domain.",
        "personal": "The rep or founder on the receiving end blames the list builder, not the data provider, because the list builder is the one in the room."
      },
      "workflow": "After the waterfall finishes in Clay and before the push to the sequencer: eyeballing the fill rate on the email column, deciding whether to run another provider or accept the gap, then watching bounces come back in Instantly or Smartlead a week later.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A verification pass strips a large share of the enriched emails",
          "cites": ["src:4"]
        },
        {
          "event": "A client or exec asks why the campaign went to half the list that was promised",
          "cites": ["src:9"]
        }
      ],
      "who_feels": ["end_user", "champion", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "632 leads with verified emails out of 1,000, and an 8% bounce rate.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "A third of every list they build is dead on arrival, and they pay for it either way.",
          "fears": "That a bad batch takes the sending domain down with it.",
          "dream_outcome": "A fill rate high enough that the list size they scoped is the list size that sends."
        },
        "champion": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I had no trust in the data that we were collecting. We needed to overhaul the data.",
              "cites": ["src:9"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "Messy CRM data isn't just annoying, it impacts your entire GTM engine.",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "Rebuilding trust in the data layer before any campaign argument can be had.",
          "fears": "Bad records flowing into the CRM and corrupting reporting downstream.",
          "dream_outcome": "Enrichment they can hand to a rep without a caveat attached."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "Clay is a solid tool, but for lead email enrichment at volume the economics stop working.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Paying a premium per record for a hit rate they could get cheaper direct from providers.",
          "fears": "Discovering the coverage gap only after the annual contract is signed.",
          "dream_outcome": "A published, verifiable match rate for their specific segment before they commit."
        }
      },
      "segments": ["seg:agency", "seg:lean", "seg:revops"],
      "feature_ref": "feat:waterfall",
      "cites": ["src:4", "src:9"]
    },
    {
      "id": "pain:sends-that-land-nowhere",
      "statement": "Thousands of emails sent, zero opens, zero replies, and no way to tell whether it was the list, the copy or the inbox.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "Campaigns that used to produce meetings stop producing anything, with no error message.",
        "operational": "Deliverability sits downstream of the data tool and upstream of the results, so when inbox placement collapses the enrichment platform still reports success while the pipeline reports nothing, and the team cannot isolate which layer failed.",
        "personal": "Whoever owns outbound has to walk into a pipeline review with a number that is zero and an explanation that sounds like an excuse."
      },
      "workflow": "The week after launch: the Clay table shows every row enriched and pushed, the sequencer shows sent, and the open rate in the reporting tab is flat. The debugging then has to happen across Clay, the sequencer, the domain warmup tool and the DNS records.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Inbox providers tighten filtering and open rates fall across every client at once",
          "cites": ["src:9"]
        },
        {
          "event": "A bounce spike from an unverified batch damages sender reputation",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["champion", "economic_buyer", "end_user"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Thousands of emails sent. Zero opens. Zero replies.",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "An entire campaign cycle and the spend behind it, with nothing to show and nothing to learn.",
          "fears": "That the channel itself is closing and the whole motion needs replacing.",
          "dream_outcome": "Knowing within a day which layer broke, and sending less to the right people rather than more to everyone."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "to_their_boss",
              "verbatim": "Instead of selling leads (which are difficult to guarantee), we scoped clearly defined deliverables.",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "Paying for a full stack whose output cannot be guaranteed to any client or board.",
          "fears": "Building a business model on a channel that can go to zero without warning.",
          "dream_outcome": "Outcomes stable enough to promise."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Over 40%+ of emails bouncing tanked our sender reputation.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Burned domains that take weeks to warm back up.",
          "fears": "Losing the company's main domain, not just the throwaways.",
          "dream_outcome": "A verification gate that makes a bounce spike impossible."
        }
      },
      "segments": ["seg:agency", "seg:lean"],
      "feature_ref": null,
      "feature_note": "feat:sequencer sends the messages but does not control inbox placement, which is set by domain reputation, warmup and the receiving provider's filters. What would kill this is a deliverability layer that gates sends on verified inbox placement and reports which layer failed when results go flat.",
      "cites": ["src:4", "src:9"]
    },
    {
      "id": "pain:it-keeps-breaking",
      "statement": "Half my week is rebuilding workflows that broke because a provider went down or an API changed.",
      "element": "b2b:ease_of_doing_business:stability",
      "shape": {
        "surface": "Tables that worked last month silently stop returning data.",
        "operational": "A build chains many external providers, so any one of them degrading breaks the chain, and because failures are silent rather than loud the break is usually found downstream when a campaign goes out wrong rather than upstream when it happens.",
        "personal": "The builder's job drifts from designing pipeline to being on call for someone else's uptime, which is neither what they were hired for nor what gets them promoted."
      },
      "workflow": "Mid-week, mid-campaign: a column in a live Clay table returns blanks, and the chase runs back through provider status pages, API keys, run conditions and credit balances before the cause is found.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A data provider changes or deprecates an API the build depends on",
          "cites": ["src:2"]
        },
        {
          "event": "Credits run out mid-run and columns fail silently",
          "cites": ["src:2"]
        }
      ],
      "who_feels": ["end_user", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Debug when providers go down. Manage credits across platforms. Rebuild workflows when they break.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Recurring unplanned hours that displace the build work they are measured on.",
          "fears": "A break they do not notice until a client or exec notices it first.",
          "dream_outcome": "Loud, specific failures with a named cause, instead of blank cells."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "A GTM Engineer building complex workflows to avoid complexity.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Owning operational risk for a stack of third parties they do not control.",
          "fears": "That the maintenance load scales with the number of plays, so success makes it worse.",
          "dream_outcome": "Builds that degrade gracefully and self-heal when a single provider drops out."
        }
      },
      "segments": ["seg:agency", "seg:revops"],
      "feature_ref": "feat:workflows",
      "cites": ["src:2"]
    },
    {
      "id": "pain:one-person-holds-it-all",
      "statement": "One person knows how the whole thing is wired, and I cannot hire a second one.",
      "element": "b2b:ease_of_doing_business:expertise",
      "shape": {
        "surface": "Job posts for the role get flooded with applicants and none of them can actually build.",
        "operational": "The skill set sits between sales and engineering with no established pipeline or interview standard, so hiring is slow and mispriced, and until the seat is filled every play queues behind whoever currently holds the knowledge.",
        "personal": "The one person who does hold it cannot take a holiday without the motion stopping, and knows it."
      },
      "workflow": "Hiring and handover: writing the job spec, sifting profiles that all list the tool but few can build in it, then trying to document a table structure well enough that someone else could pick it up.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "The person who built the tables resigns or goes on leave",
          "cites": ["src:11"]
        },
        {
          "event": "A hire is made, does not work out, and the search restarts",
          "cites": ["src:11", "src:17"]
        },
        {
          "event": "Contractor rates come in above what a full-time offer was budgeted at",
          "cites": ["src:17"]
        }
      ],
      "who_feels": ["economic_buyer", "champion", "blocker"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Struggling to hire a GTM Engineer? Getting flooded with profiles but none feel right?",
              "cites": ["src:11"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Avoid the very expensive \"wrong hire → restart\" loop.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "A six-figure salary plus months of empty seat, against a role with no benchmark to price it.",
          "fears": "That the wrong hire in this seat quietly caps the entire pipeline.",
          "dream_outcome": "A platform their existing ops person can run without a specialist hire."
        },
        "champion": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "A $150K-$250K band-aid on a broken process.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Being the single point of failure for every play the company runs.",
          "fears": "That the knowledge never transfers and they can never move off the tool.",
          "dream_outcome": "Builds legible enough that a new joiner is productive in a week."
        },
        "blocker": {
          "says": [
            {
              "situation": "when_refusing",
              "verbatim": "If the bottleneck is leadership you can hire all the builders you want but they'll just be building the wrong things faster.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Headcount spent on tooling rather than on selling.",
          "fears": "Funding a role that is a workaround for a tool that was supposed to remove the role.",
          "dream_outcome": "Pipeline growth that does not require a new specialist function to exist."
        }
      },
      "segments": ["seg:lean", "seg:revops", "seg:agency"],
      "feature_ref": null,
      "feature_note": "feat:claygents automates the research a person used to do, but the scarce skill is designing and maintaining the system, not running the research. What would kill this is prebuilt, editable plays that ship working out of the box so the platform does not presuppose a specialist.",
      "cites": ["src:2", "src:11", "src:16", "src:17"]
    },
    {
      "id": "pain:the-ground-moved",
      "statement": "The pricing changed under me and the one thing my whole build depends on now sits behind a plan I never needed.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "A repricing moves a previously free or cheap capability into a higher tier.",
        "operational": "Builds that route through custom API calls are priced by the vendor's plan structure rather than by usage, so a tier change resets the unit economics of every client campaign at once, with a hard deadline to decide before grandfathering lapses.",
        "personal": "Operators who evangelised the tool publicly feel their loyalty was the thing being repriced."
      },
      "workflow": "Reading the pricing change notice, then going table by table to find every HTTP API column, and modelling whether client retainers still clear margin on the new plan before the grandfathering deadline.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Clay's March 2026 repricing split billing into Actions and Data Credits and moved HTTP API access to the $495 Growth tier",
          "cites": ["src:6", "src:7"]
        },
        {
          "event": "The April 10, 2026 deadline after which any plan change forces migration off legacy pricing",
          "cites": ["src:7"]
        }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "just a SINGLE custom API call to my own DB...now requires me to spend $500 bucks.",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "What about the younger versions of us? Clay used to be a community fueled by enthusiastic individuals.",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "A cost base that rises on a retainer they cannot reprice mid-contract.",
          "fears": "That the next change lands the same way and there is no way to plan around it.",
          "dream_outcome": "Pricing that moves with their usage, not with the vendor's segment strategy."
        },
        "champion": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "People like me are system exploiters. We find the loops, stack the workflows, and squeeze 10x or maybe 100x value out of every plan. Clay just decided to close some of those loops. Fair enough.",
              "cites": ["src:8"]
            },
            {
              "situation": "when_looking",
              "verbatim": "We will likely recommend staying on Legacy if you are paying less.",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "Re-architecting working builds to fit a new billing model rather than a new requirement.",
          "fears": "Being locked out of legacy pricing by a deadline they miss.",
          "dream_outcome": "A pricing model stable enough to build a two-year business plan on."
        }
      },
      "segments": ["seg:agency", "seg:lean"],
      "feature_ref": null,
      "feature_note": "This is a commercial pain, not a product gap. What would address it is grandfathering with no expiry plus advance notice windows long enough to re-architect, which is partly what the legacy plan policy already does for enterprise.",
      "cites": ["src:6", "src:7", "src:8"]
    },
    {
      "id": "pain:signals-without-a-reason",
      "statement": "Everyone gets the same funding alert at the same minute, so the signal tells me when but never why.",
      "element": "b2b:ease_of_doing_business:information",
      "shape": {
        "surface": "Signal feeds produce more alerts than anyone can act on, and the obvious ones are saturated.",
        "operational": "A signal is a timestamp, not a reason, so acting on it without mapping it to a problem the account actually has produces messages that open with a congratulation and then say nothing, and because every competitor subscribes to the same feed the same account gets the same email from ten vendors in one week.",
        "personal": "Reps get trained into a habit that feels like research and reads like a mail merge, and their reply rates fall while their activity numbers look fine."
      },
      "workflow": "The morning signal review: a queue of funding rounds, job changes and hiring alerts in Clay or the CRM, and a decision on each about whether there is a real reason to write, usually made in seconds and usually answered yes.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "A funding announcement fires alerts to every vendor watching the account simultaneously",
          "cites": ["src:10"]
        },
